std::vector<std::vector<Point>> face_polygons;
std::vector<double> edge_lengths;

for (auto e = rt.finite_edges_begin(); e != rt.finite_edges_end(); ++e) {
    if (is_small_edge(rt, *e, threshold)) {
        continue;
    }

    std::vector<Point> polygon;
    auto c1 = rt.cell(e->first);
    auto c2 = rt.cell(e->second);

    for (int i = 0; i < 4; ++i) {
        if (c1->vertex(i) == c2->vertex(i)) {
            polygon.push_back(c1->vertex(i)->point());
        }
    }

    face_polygons.push_back(polygon);
    edge_lengths.push_back(std::sqrt(rt.segment(*e).squared_length()));
}

Mesh<Point, double> mesh;
mesh Reserve(face_polygons.size(), edge_lengths.size());
for (size_t i = 0; i < face_polygons.size(); ++i) {
    mesh.add_face(face_polygons[i]);
}
for (size_t i = 0; i < edge_lengths.size(); ++i) {
    mesh.add_edge_length(edge_lengths[i]);
}

return mesh;

